input.content:
/**
 * The subscription is the single authority on a workspace's plan: everything
 * that depends on the plan follows it the moment it changes, workspaces whose
 * records already disagree are corrected without another plan change, and the
 * trial sweep only touches subscriptions that are still on trial.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { isEnabled } from "@/lib/feature-flags";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { getDb } from "@/server/db";
import { organizations, subscriptions } from "@/server/db/schema";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as billingService from "@/server/services/billing-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

function projectInput(orgId: OrgId, n: number): CreateProjectInput {
  return {
    orgId,
    name: `Project ${n}`,
    slug: `project-${n}`,
    key: `P${n}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

/** Rewrites only the subscription row, the way a billing-side change would. */
function setSubscriptionPlan(orgId: OrgId, plan: PlanId, status = "active") {
  getDb()
    .update(subscriptions)
    .set({ plan, status: status as "active" | "trialing" })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

function setStoredOrgPlan(orgId: OrgId, plan: PlanId) {
  getDb().update(organizations).set({ plan }).where(eq(organizations.id, orgId)).run();
}

async function planShown(tenant: Tenant): Promise<PlanId | undefined> {
  return (await orgRepo.findOrgById(tenant.org.id))?.plan;
}

describe("plan follows the subscription", () => {
  it("lifts every quota, flag and displayed plan after an upgrade", async () => {
    const tenant = await createTenant("authority-upgrade", "free");
    setSubscriptionPlan(tenant.org.id, "free");
    await usageRepo.recomputeUsage(tenant.org.id);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(await planShown(tenant)).toBe("growth");
    expect((await orgRepo.findOrgBySlug("authority-upgrade"))?.plan).toBe("growth");
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.plan).toBe("growth");

    // Free allows two projects; the tenant already holds one and now adds two.
    await projectService.createProject(tenant.actors.owner, projectInput(tenant.org.id, 1));
    await projectService.createProject(tenant.actors.owner, projectInput(tenant.org.id, 2));

    // Free allows three seats; four members are already seated.
    await usageRepo.recomputeUsage(tenant.org.id);
    const invited = await invitationService.inviteMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      invites: [{ email: "new@authority-upgrade.test", role: "member" }],
    });
    expect(invited).toHaveLength(1);

    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(isEnabled("csv_export", buildFlagContext(tenant.actors.owner, org))).toBe(true);
  });

  it("removes plan-gated features after a downgrade", async () => {
    const tenant = await createTenant("authority-downgrade", "growth");

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    await expect(
      webhookService.createWebhook(tenant.actors.owner, {
        orgId: tenant.org.id,
        url: "https://example.com/hook",
        eventTypes: ["billing.plan_changed"],
      }),
    ).rejects.toThrow(/not included/);
  });

  it("corrects a workspace whose records already disagree", async () => {
    const tenant = await createTenant("authority-drift", "free");
    setSubscriptionPlan(tenant.org.id, "growth");
    expect(
      (await subscriptionRepo.findSubscription(tenant.org.id))?.plan,
    ).toBe("growth");

    expect(await planShown(tenant)).toBe("growth");
    expect((await billingService.checkLimit(tenant.org.id, "projects")).plan).toBe("growth");
    await projectService.createProject(tenant.actors.owner, projectInput(tenant.org.id, 1));
    await projectService.createProject(tenant.actors.owner, projectInput(tenant.org.id, 2));

    setSubscriptionPlan(tenant.org.id, "starter");
    setStoredOrgPlan(tenant.org.id, "enterprise");
    expect(await planShown(tenant)).toBe("starter");
  });

  it("uses the plan stored on the workspace when there is no subscription", async () => {
    const tenant = await createTenant("authority-nosub", "free");
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).run();
    setStoredOrgPlan(tenant.org.id, "starter");

    expect(await planShown(tenant)).toBe("starter");
    expect((await billingService.checkLimit(tenant.org.id, "seats")).limit).toBe(10);
  });

  it("never lets one workspace's plan affect another", async () => {
    const a = await createTenant("authority-iso-a", "free");
    const b = await createTenant("authority-iso-b", "free");
    setSubscriptionPlan(a.org.id, "free");
    setSubscriptionPlan(b.org.id, "free");

    setSubscriptionPlan(a.org.id, "enterprise");

    expect(await planShown(a)).toBe("enterprise");
    expect(await planShown(b)).toBe("free");
    expect((await billingService.checkLimit(b.org.id, "projects")).plan).toBe("free");
  });

  it("changes nothing when a plan change is refused", async () => {
    const tenant = await createTenant("authority-refused", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });

    await expect(
      billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "free",
        interval: "monthly",
      }),
    ).rejects.toThrow();

    expect(await planShown(tenant)).toBe("growth");
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("growth");
  });
});

describe("burst limits follow the subscription", () => {
  it("sizes buckets from the subscription's plan, not a stale record", async () => {
    const tenant = await createTenant("authority-burst", "free");
    setSubscriptionPlan(tenant.org.id, "growth");

    let allowed = 0;
    for (let i = 0; i < 200; i += 1) {
      if ((await consumeRateLimit(tenant.org.id, "comment:create")).allowed) allowed += 1;
    }
    expect(allowed).toBe(200);
  });

  it("resizes an existing bucket as soon as the plan changes", async () => {
    const tenant = await createTenant("authority-burst-live", "free");
    setSubscriptionPlan(tenant.org.id, "free");

    for (let i = 0; i < 60; i += 1) {
      expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(true);
    }
    expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(false);

    setSubscriptionPlan(tenant.org.id, "growth");
    expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(true);

    setSubscriptionPlan(tenant.org.id, "free");
    const remaining = (await consumeRateLimit(tenant.org.id, "comment:create")).remaining;
    expect(remaining).toBeLessThanOrEqual(60);
  });
});

describe("trial expiry sweep", () => {
  const AFTER_TRIAL = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

  it("moves an expired trial to free everywhere, and only once", async () => {
    const tenant = await createTenant("authority-trial", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    // Two members' worth of seats fit on free only if the org is small enough.
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: -1 });

    const first = await runTrialExpiryJob(AFTER_TRIAL);
    expect(first.processed).toBeGreaterThanOrEqual(1);

    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("free");
    expect(await planShown(tenant)).toBe("free");
    expect((await billingService.checkLimit(tenant.org.id, "projects")).plan).toBe("free");

    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    const second = await runTrialExpiryJob(AFTER_TRIAL);
    expect(second.processed).toBe(0);
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
  });

  it("leaves a subscription alone once the org chose a paid plan", async () => {
    const tenant = await createTenant("authority-chose", "growth");
    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    await runTrialExpiryJob(AFTER_TRIAL);

    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("starter");
    expect(await planShown(tenant)).toBe("starter");
  });

  it("leaves a trial that outgrew the free limits on its plan", async () => {
    const tenant = await createTenant("authority-outgrown", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { projectsUsed: 5 });

    await runTrialExpiryJob(AFTER_TRIAL);

    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("growth");
    expect(await planShown(tenant)).toBe("growth");
  });
});

