        url: "https://example.com/hook",
        eventTypes: ["billing.plan_changed"],
      }),
    ).rejects.toThrow(/not included/);
  });

  it("corrects a workspace whose records already disagree", async () => {
    const tenant = await createTenant("authority-drift", "free");
    setSubscriptionPlan(tenant.org.id, "growth");
    expect(
      (await subscriptionRepo.findSubscription(tenant.org.id))?.plan,
    ).toBe("growth");

    expect(await planShown(tenant)).toBe("growth");
    expect((await billingService.checkLimit(tenant.org.id, "projects")).plan).toBe("growth");
