import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { getDb } from "@/server/db";
import { organizations, subscriptions } from "@/server/db/schema";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as billingService from "@/server/services/billing-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

function projectInput(orgId: OrgId, n: number): CreateProjectInput {
  return {
    orgId,
    name: `Project ${n}`,
    slug: `project-${n}`,
    key: `P${n}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

/** Rewrites only the subscription row, the way a billing-side change would. */
function setSubscriptionPlan(orgId: OrgId, plan: PlanId, status = "active") {
  getDb()
    .update(subscriptions)
    .set({ plan, status: status as "active" | "trialing" })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

function setStoredOrgPlan(orgId: OrgId, plan: PlanId) {
  getDb().update(organizations).set({ plan }).where(eq(organizations.id, orgId)).run();
}

async function planShown(tenant: Tenant): Promise<PlanId | undefined> {
  return (await orgRepo.findOrgById(tenant.org.id))?.plan;
}

